"""Edge-case tests for chart-annotations-composition -- generated by bug-hunter agent.

Focus areas:
1. __add__ with annotation primitives: early guard behavior, both-sides annotations
2. configure_*() on composed types: propagation through nested compositions, rebuild survival
3. Annotation primitives: correct attachment, clone survival, all annotate_* functions
4. Interactive rendering: annotations in interactive mode
5. Edge cases: empty data, null data, type mismatches, degenerate domains
"""

from __future__ import annotations

import copy
import warnings

import polars as pl
import pytest

import ferrum as fr
from ferrum import Chart
from ferrum.annotations import (
    annotate_abline,
    annotate_arrow,
    annotate_hline,
    annotate_rect,
    annotate_text,
    annotate_vline,
)
from ferrum.composition import (
    ConcatChart,
    HConcatChart,
    JointChart,
    LayerChart,
    VConcatChart,
    _copy_configure_layers,
)
from ferrum.configure import (
    AxisConfig,
    ColorConfig,
    Configure,
    GridConfig,
    LegendConfig,
    PaddingConfig,
    TitleConfig,
)


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _simple_chart(data=None, mark="point"):
    if data is None:
        data = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
    c = Chart(data)
    if mark == "point":
        c = c.mark_point()
    elif mark == "line":
        c = c.mark_line()
    elif mark == "bar":
        c = c.mark_bar()
    return c.encode(x="x", y="y")


def _assert_valid_svg(svg: str) -> None:
    assert isinstance(svg, str), f"Expected str, got {type(svg).__name__}"
    assert svg.startswith("<svg") or svg.startswith("<?xml"), f"Bad SVG start: {svg[:80]!r}"
    assert "NaN" not in svg, "SVG contains 'NaN'"
    assert "Infinity" not in svg, "SVG contains 'Infinity'"


