class TestAddAnnotationPrimitive:
    """Tests targeting the __add__ early-return guard at chart.py:4117-4121."""

    def test_annotate_hline_sets_annotation_primitive(self):
        """annotate_hline should set _annotation_primitive on the returned chart.

        Targets annotations.py:76 _attach_annotation_primitive call.
        """
        ann = annotate_hline(5.0)
        assert ann._annotation_primitive is not None

    def test_annotate_vline_sets_annotation_primitive(self):
        """annotate_vline should set _annotation_primitive on the returned chart.

        Targets annotations.py:130 _attach_annotation_primitive call.
        """
        ann = annotate_vline(3.0)
        assert ann._annotation_primitive is not None

    def test_annotate_rect_sets_annotation_primitive(self):
        """annotate_rect should set _annotation_primitive on the returned chart.

        Targets annotations.py:196 _attach_annotation_primitive call.
        """
        ann = annotate_rect(0, 0, 1, 1)
        assert ann._annotation_primitive is not None

    def test_annotate_text_sets_annotation_primitive(self):
        """annotate_text should set _annotation_primitive on the returned chart.

        Targets annotations.py:280 _attach_annotation_primitive call.
        """
        ann = annotate_text(1.0, 2.0, "label")
        assert ann._annotation_primitive is not None

    def test_annotate_abline_sets_annotation_primitive(self):
        """annotate_abline should set _annotation_primitive on the returned chart.

        Targets annotations.py:352 _attach_annotation_primitive call.
        """
        ann = annotate_abline(slope=1.0, intercept=0.0)
        assert ann._annotation_primitive is not None

    def test_annotate_arrow_does_not_set_annotation_primitive(self):
        """annotate_arrow does NOT call _attach_annotation_primitive.

        This is an intentional gap or a bug -- annotate_arrow returns a plain
        chart (or VConcatChart when label is set) without annotation routing.
        Targets annotations.py:407-428.
        """
        ann = annotate_arrow(0, 0, 1, 1)
        # annotate_arrow does not attach _annotation_primitive
        assert ann._annotation_primitive is None

    def test_chart_plus_annotate_hline_routes_through_annotations(self):
        """chart + annotate_hline() should add to _annotations, NOT _layers.

        Targets chart.py:4117-4121: the annotation primitive early guard.
        The RHS mark layers from annotate_hline (mark_rule) should be excluded
        from the merged layers since the annotation primitive handles rendering.
        """
        c = _simple_chart()
        hline = annotate_hline(5.0, stroke="red")
        result = c + hline
        # The annotation primitive should be wrapped in Annotate and stored
        assert len(result._annotations) == 1
        # The RHS mark_rule layers should NOT appear in _layers
        # (LHS had no layers, so _expand_layers returns a single-element list)
        assert result._layers is not None
        layer_marks = [l.mark for l in result._layers]
        # Only LHS layers should be present
        assert "rule" not in layer_marks, (
            "RHS annotation mark_rule leaked into layers -- would cause duplicate rendering"
        )

    def test_chart_plus_annotate_abline_routes_through_annotations(self):
        """chart + annotate_abline() should go through annotation path.

        Targets chart.py:4117-4121: abline has _annotation_primitive set.
        """
        c = _simple_chart()
        abl = annotate_abline(slope=1.0, intercept=0.0, stroke="gray")
        result = c + abl
        assert len(result._annotations) == 1
        # abline mark_line layers should NOT be in the merged layers
        layer_marks = [l.mark for l in result._layers]
        assert "line" not in layer_marks

    def test_chart_plus_annotate_text_routes_through_annotations(self):
        """chart + annotate_text() should go through annotation path."""
        c = _simple_chart()
        txt = annotate_text(2.0, 5.0, "peak")
        result = c + txt
        assert len(result._annotations) == 1
        layer_marks = [l.mark for l in result._layers]
        assert "text" not in layer_marks

    def test_chart_plus_annotate_rect_routes_through_annotations(self):
        """chart + annotate_rect() should go through annotation path."""
        c = _simple_chart()
        rect = annotate_rect(1, 1, 2, 5)
        result = c + rect
        assert len(result._annotations) == 1
        layer_marks = [l.mark for l in result._layers]
        assert "rect" not in layer_marks

    def test_chart_plus_regular_chart_does_not_trigger_annotation_guard(self):
        """chart + chart (no annotation primitive) should NOT skip RHS layers.

        Targets chart.py:4117: rhs._annotation_primitive is None for normal charts.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="line")
        result = c1 + c2
        assert len(result._annotations) == 0
        assert result._layers is not None
        assert len(result._layers) == 2
        marks = [l.mark for l in result._layers]
        assert "point" in marks
        assert "line" in marks

    def test_annotation_chart_as_lhs_should_route_through_annotations(self):  # BUG: hline + chart loses annotation routing
        """When an annotation chart is the LHS of +, its annotation should be
        routed the same way as when it is on the RHS.

        Targets chart.py:4117: only checks rhs._annotation_primitive, not lhs.
        Currently annotate_hline(5) + chart produces a rule layer (duplication)
        while chart + annotate_hline(5) properly routes through _annotations.
        """
        hline = annotate_hline(5.0, stroke="red")
        c = _simple_chart()
        result = hline + c

        # The annotation from the LHS should appear in _annotations
        assert len(result._annotations) >= 1, (
            "LHS annotation primitive was not converted to an annotation entry; "
            "hline + chart is asymmetric with chart + hline"
        )

    def test_both_sides_have_annotation_primitives(self):
        """chart + annotation1 + annotation2 should accumulate both annotations.

        Targets chart.py:4117-4121: sequential annotation adds.
        """
        c = _simple_chart()
        result = c + annotate_hline(5.0) + annotate_vline(2.0)
        assert len(result._annotations) == 2

    def test_chart_with_annotations_plus_annotation(self):
        """A chart that already has annotations from + should accumulate more.

        Targets chart.py:4119: new._annotations = new._annotations + [Annotate(...)].
        """
        c = _simple_chart()
        c = c + annotate_hline(5.0)
        c = c + annotate_text(1.0, 5.0, "Hi")
        c = c + annotate_rect(0, 0, 3, 7)
        assert len(c._annotations) == 3

    def test_annotation_chart_plus_regular_chart_renders(self):
        """annotate_hline + chart should produce valid SVG even if primitive is lost.

        Targets the rendering path -- even if the annotation routing is wrong,
        the SVG should be structurally valid.
        """
        hline = annotate_hline(5.0, stroke="red")
        c = _simple_chart()
        result = hline + c
        svg = result.show_svg()
        _assert_valid_svg(svg)

    def test_chart_plus_annotation_renders_valid_svg(self):
        """chart + annotate_hline() should render valid SVG with annotation.

        Contract pin: the annotation should appear as a rendered element.
        """
        c = _simple_chart()
        result = c + annotate_hline(5.0, stroke="red")
        svg = result.show_svg()
        _assert_valid_svg(svg)

    def test_chart_plus_annotation_data_not_merged(self):
        """When RHS is annotation chart, its data should NOT be merged with LHS.

        Targets chart.py:4118: 'new._layers = lhs_layers' -- no data merge.
        The annotation chart's data (e.g. {'_y': [5.0]}) should not pollute
        the main chart's data.
        """
        df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        c = Chart(df).mark_point().encode(x="x", y="y")
        result = c + annotate_hline(5.0)
        # The data should still be the original 2 rows
        assert result._data is not None
        result_df = result._data
        if isinstance(result_df, pl.DataFrame):
            assert result_df.height == 2
            assert "_y" not in result_df.columns


