# 2. _annotation_primitive clone survival
# ===========================================================================


class TestAnnotationPrimitiveCloneSurvival:
    """Test that _annotation_primitive survives Chart._clone()."""

    def test_clone_preserves_annotation_primitive(self):
        """Chart._clone() should copy _annotation_primitive.

        Targets chart.py:344: new._annotation_primitive = self._annotation_primitive.
        """
        ann = annotate_hline(5.0)
        cloned = ann._clone()
        assert cloned._annotation_primitive is ann._annotation_primitive

    def test_encode_after_annotate_preserves_primitive(self):
        """Calling encode() after annotate_*() should preserve the primitive.

        This tests the immutability chain: annotate_hline creates a chart,
        then encode() clones it. The clone should preserve _annotation_primitive.
        """
        # annotate_hline already calls .encode(y="_y"), so we test additional encode
        ann = annotate_hline(5.0)
        # The annotation primitive should survive
        assert ann._annotation_primitive is not None

    def test_theme_after_annotate_preserves_primitive(self):
        """Calling .theme() on an annotation chart should preserve the primitive."""
        ann = annotate_hline(5.0)
        themed = ann.theme(fr.themes.dark)
        assert themed._annotation_primitive is not None

    def test_properties_after_annotate_preserves_primitive(self):
        """Calling .properties() on an annotation chart preserves the primitive."""
        ann = annotate_hline(5.0)
        updated = ann.properties(width=800)
        assert updated._annotation_primitive is not None


