# 3. configure_*() on composed types -- propagation and rebuild survival
# ===========================================================================


class TestConfigurePropagation:
    """Tests for configure_*() methods on _ChartLike compositions."""

    def test_configure_axis_on_hconcat_creates_configure_layers(self):
        """configure_axis on HConcatChart should add to _configure_layers.

        Targets composition.py:290-361: configure_axis on _ChartLike.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure_axis(label_angle=-45)
        assert hasattr(combined, "_configure_layers")
        assert len(combined._configure_layers) == 1

    def test_configure_legend_on_vconcat_creates_configure_layers(self):
        """configure_legend on VConcatChart should add to _configure_layers."""
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 & c2).configure_legend(orient="bottom")
        assert len(combined._configure_layers) == 1

    def test_configure_title_on_concat_creates_configure_layers(self):
        """configure_title on ConcatChart should add to _configure_layers."""
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = ConcatChart(c1, c2).configure_title(font_size=18)
        assert len(combined._configure_layers) == 1

    def test_configure_grid_on_layer_chart(self):
        """configure_grid on LayerChart should add to _configure_layers."""
        c1 = _simple_chart()
        c2 = _simple_chart(mark="line")
        combined = LayerChart(c1, c2).configure_grid(x=True, y=True)
        assert len(combined._configure_layers) == 1

    def test_configure_padding_on_joint_chart(self):
        """configure_padding on JointChart should add to _configure_layers."""
        df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [4.0, 5.0, 6.0]})
        center = Chart(df).mark_point().encode(x="x", y="y")
        top = Chart(df).mark_point().encode(x="x", y="y")
        joint = JointChart(center, top=top).configure_padding(top=20)
        assert len(joint._configure_layers) == 1

    def test_configure_color_on_repeat_chart(self):
        """configure_color on RepeatChart should add to _configure_layers."""
        df = pl.DataFrame({"a": [1.0, 2.0], "b": [3.0, 4.0]})
        template = Chart(df).encode(x=fr.Repeat.column, y="a").mark_point()
        rc = fr.RepeatChart(template, column=["a", "b"]).configure_color(
            scheme="tableau10"
        )
        assert len(rc._configure_layers) == 1

    def test_multiple_configure_calls_accumulate(self):
        """Multiple configure_*() calls should accumulate, not replace.

        Targets composition.py:360: list(getattr(...)) + [Configure(...)].
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (
            (c1 | c2)
            .configure_axis(label_angle=-30)
            .configure_grid(color="#eee")
            .configure_padding(top=10)
        )
        assert len(combined._configure_layers) == 3

    def test_configure_survives_theme_rebuild(self):
        """configure_layers should survive .theme() on a composition.

        Targets composition.py:241: _copy_configure_layers(self, result).
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure_axis(label_angle=-45)
        themed = combined.theme(fr.themes.dark)
        assert hasattr(themed, "_configure_layers")
        assert len(themed._configure_layers) == 1

    def test_configure_survives_properties_rebuild(self):
        """configure_layers should survive .properties() on a composition.

        Targets composition.py:259: _copy_configure_layers(self, result).
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure_axis(label_angle=-45)
        updated = combined.properties(width=800)
        assert len(updated._configure_layers) == 1

    def test_configure_survives_share_scale_rebuild(self):
        """configure_layers should survive .share_scale() on a composition.

        Targets composition.py:223: _copy_configure_layers(self, result).
        """
        df1 = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        df2 = pl.DataFrame({"x": [10.0, 20.0], "y": [30.0, 40.0]})
        c1 = Chart(df1).mark_point().encode(x="x", y="y")
        c2 = Chart(df2).mark_point().encode(x="x", y="y")
        combined = (c1 | c2).configure_axis(label_angle=-45)
        shared = combined.share_scale(x="shared")
        assert len(shared._configure_layers) == 1

    def test_inject_parent_config_chart_child(self):
        """_inject_parent_config prepends config to child Chart._configure.

        Targets composition.py:285-288: plain Chart child path.
        """
        df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        c = Chart(df).mark_point().encode(x="x", y="y")
        # Chart with its own configure
        c = c.configure_axis(label_angle=0)
        assert len(c._configure) == 1

        parent = HConcatChart([c]).configure_axis(label_angle=-30)
        injected = parent._inject_parent_config(c)
        # Parent config should be prepended
        assert len(injected._configure) == 2
        # Parent's config should be first (so child's wins on conflict)

    def test_inject_parent_config_nested_composition(self):
        """_inject_parent_config on a nested _ChartLike merges _configure_layers.

        Targets composition.py:279-283: nested composition child path.
        """
        df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        c1 = Chart(df).mark_point().encode(x="x", y="y")
        c2 = Chart(df).mark_bar().encode(x="x", y="y")
        inner = c1 | c2
        inner = inner.configure_axis(label_angle=0)

        outer = HConcatChart([inner]).configure_axis(label_angle=-30)
        injected = outer._inject_parent_config(inner)
        # Should be a _ChartLike with merged _configure_layers
        assert hasattr(injected, "_configure_layers")
        assert len(injected._configure_layers) == 2

    def test_inject_parent_config_no_config_is_noop(self):
        """_inject_parent_config with no _configure_layers returns chart unchanged.

        Targets composition.py:277: early return when config is falsy.
        """
        df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        c = Chart(df).mark_point().encode(x="x", y="y")
        parent = HConcatChart([c])
        # No configure_layers set
        injected = parent._inject_parent_config(c)
        assert injected is c  # same object, not a clone

    def test_configure_renders_through_hconcat(self):
        """Composition-level configure should actually affect SVG rendering.

        Targets the full pipeline: configure_axis -> _inject_parent_config ->
        _resolve_chart_config -> render_svg.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure_axis(label_angle=-45)
        svg = combined.show_svg()
        _assert_valid_svg(svg)

    def test_configure_renders_through_vconcat(self):
        """Composition-level configure should work through VConcat."""
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 & c2).configure_grid(color="#ccc")
        svg = combined.show_svg()
        _assert_valid_svg(svg)

    def test_configure_renders_through_concat_chart(self):
        """Composition-level configure should work through ConcatChart."""
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = ConcatChart(c1, c2).configure_legend(orient="bottom")
        svg = combined.show_svg()
        _assert_valid_svg(svg)


# ===========================================================================
# 4. _copy_configure_layers edge cases
# ===========================================================================


class TestCopyConfigureLayers:
    """Tests for the _copy_configure_layers helper."""

    def test_copy_from_source_without_attribute(self):
        """_copy_configure_layers should be a no-op if src has no _configure_layers.

        Targets composition.py:25-27: getattr returns None.
        """
        class FakeSrc:
            pass

        class FakeDst:
            pass

        src = FakeSrc()
        dst = FakeDst()
        # Should not raise
        _copy_configure_layers(src, dst)
        assert not hasattr(dst, "_configure_layers")

    def test_copy_from_empty_list_is_noop(self):
        """_copy_configure_layers with empty list does not copy.

        Targets composition.py:26: 'if config:' is falsy for empty list.
        """
        class FakeSrc:
            _configure_layers = []

        class FakeDst:
            pass

        src = FakeSrc()
        dst = FakeDst()
        _copy_configure_layers(src, dst)
        # Empty list is falsy, so _configure_layers should not be set on dst
        assert not hasattr(dst, "_configure_layers")

    def test_copy_creates_new_list(self):
        """_copy_configure_layers should create a new list, not alias.

        Targets composition.py:27: dst._configure_layers = list(config).
        """
        cfg = Configure(axis=AxisConfig(label_angle=-30))

        class FakeSrc:
            _configure_layers = [cfg]

        class FakeDst:
            pass

        src = FakeSrc()
        dst = FakeDst()
        _copy_configure_layers(src, dst)
        assert dst._configure_layers == [cfg]
        assert dst._configure_layers is not src._configure_layers


