class TestConfigureGenericMethod:
    """Tests for the generic configure() method on _ChartLike."""

    def test_configure_generic_on_hconcat(self):
        """configure() generic method should work on HConcatChart.

        Targets composition.py:538-577.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure(
            axis=AxisConfig(label_angle=-30),
            legend=LegendConfig(orient="bottom"),
        )
        assert len(combined._configure_layers) == 1
        cfg = combined._configure_layers[0]
        assert cfg.axis is not None
        assert cfg.legend is not None

    def test_configure_generic_with_all_none_is_valid(self):
        """configure() with all defaults should add a Configure with all None fields.

        This is a degenerate but valid call.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        combined = (c1 | c2).configure()
        assert len(combined._configure_layers) == 1
        cfg = combined._configure_layers[0]
        assert cfg.axis is None


