# 11. _attach_annotation_primitive mutates in place
# ===========================================================================


class TestAttachAnnotationPrimitive:
    """Tests for the _attach_annotation_primitive function."""

    def test_mutates_chart_in_place(self):
        """_attach_annotation_primitive mutates the chart, not clones.

        Targets annotations.py:20: 'chart._annotation_primitive = primitive'
        This is safe for annotate_* helpers because they create fresh charts,
        but the function signature is misleading -- it modifies and returns
        the same object.
        """
        from ferrum.annotations import _attach_annotation_primitive
        from ferrum.annotation.primitives import AnnotationLine
        from ferrum.annotation.coords import norm

        df = pl.DataFrame({"x": [1.0], "y": [2.0]})
        chart = Chart(df).mark_rule().encode(y="y")
        prim = AnnotationLine(
            x1=norm(0), y1=5.0, x2=norm(1), y2=5.0,
            stroke="#333", stroke_width=1, dash=None,
        )
        result = _attach_annotation_primitive(chart, prim)
        # result IS chart (same object), not a clone
        assert result is chart
        assert chart._annotation_primitive is prim


