# 15. configure_*() immutability
# ===========================================================================


class TestConfigureImmutability:
    """Verify that configure_*() returns new compositions, not mutations."""

    def test_configure_axis_does_not_mutate_original(self):
        """configure_axis should return a new composition, not mutate.

        Targets composition.py:359: new = copy.copy(self).
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        original = c1 | c2
        configured = original.configure_axis(label_angle=-45)
        # Original should not have _configure_layers
        assert not getattr(original, "_configure_layers", [])
        # Configured should have it
        assert len(configured._configure_layers) == 1

    def test_configure_on_chart_does_not_mutate(self):
        """configure_axis on a plain Chart should not mutate the original."""
        c = _simple_chart()
        configured = c.configure_axis(label_angle=-30)
        assert len(c._configure) == 0
        assert len(configured._configure) == 1

    def test_configure_axis_shallow_copy_aliasing_hconcat(self):  # BUG: charts list shared after configure
        """configure_axis uses copy.copy which shares the charts list on HConcatChart.

        Targets composition.py:359: new = copy.copy(self).
        copy.copy on _CompositeBase creates a shallow copy, so the charts
        list is shared between the original and the copy. Mutating one's
        charts list affects the other, violating immutability.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        original = HConcatChart([c1, c2])
        configured = original.configure_axis(label_angle=-45)

        # The charts list should NOT be shared
        assert original.charts is not configured.charts, (
            "copy.copy shares the charts list between original and configured; "
            "mutating original.charts after configure_axis() would corrupt the configured copy"
        )

    def test_configure_axis_shallow_copy_aliasing_vconcat(self):  # BUG: charts list shared after configure
        """configure_axis uses copy.copy which shares the charts list on VConcatChart.

        Same shallow copy aliasing bug as HConcatChart.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="bar")
        original = VConcatChart([c1, c2])
        configured = original.configure_axis(label_angle=-45)

        assert original.charts is not configured.charts, (
            "copy.copy shares the charts list between original and configured VConcatChart"
        )

    def test_configure_axis_shallow_copy_aliasing_layer_chart(self):  # BUG: _charts list shared after configure
        """configure_axis uses copy.copy which shares _charts on LayerChart.

        LayerChart uses __slots__ with _charts, but copy.copy still shallow-copies
        the list reference.
        """
        c1 = _simple_chart()
        c2 = _simple_chart(mark="line")
        original = LayerChart(c1, c2)
        configured = original.configure_axis(label_angle=-45)

        assert original._charts is not configured._charts, (
            "copy.copy shares the _charts list between original and configured LayerChart"
        )


